// ベクトル列2つから交叉判定。trueの場合、交叉する。
function collisionTwoConvexQuad(quad0, quad1){
  return !nonCollisionTwoConvexQuad(quad0, quad1) && !nonCollisionTwoConvexQuad(quad1, quad0);
}

// 凸四角形同士の交叉判定
function nonCollisionTwoConvexQuad(quad0, quad1){
  // quad0から見てquad1が衝突しない場合にfalseを返す。
  const vs = [];
  for(let i=0; i<2; i++){
    vs.push(quad0[i+1].copy().sub(quad0[i]));
  }
  const quadSign = (vs[0].x*vs[1].y - vs[1].x*vs[0].y < 0 ? -1 : 1);
  const calcValue = (v,w,u) => Math.sign((w.x-v.x)*(u.y-v.y) - (w.y-v.y)*(u.x-v.x));
  for(let i=0;i<4;i++){
    let cc = 0;
    for(let k=0;k<4;k++){
      if(calcValue(quad0[i],quad0[(i+1)%4],quad1[k]) * quadSign < 0) cc++;
    }
    if(cc === 4) return true;
  }
  return false;
}

