function createUnit(){
  // サイズと寿命を比例させる
  const fishSize = random(0.5,1) * max(width, height)/15;
  return new FlowUnit({
    x:random(0.1,0.9)*width, y:random(0.1,0.9)*height,
    appearDuration:floor(random(60,180)),
    vanishDuration:floor(random(100,220)),
    life:fishSize*20,
    velocity:random(1,3),direction:random(6.28),
    acceleFactor:random(0.1,0.2),noiseFactor:random(0.01,0.05),
    noiseIndex:floor(random(9999)), fishSize:fishSize
  });
}

class FlowUnit{
  constructor(params = {}){
    const {
      x=width/2, y=height/2,
      appearDuration = 120, vanishDuration = 180, life = 700,
      velocity = 2, direction = 0,
      acceleFactor = 0.15, noiseFactor = 0.02,
      noiseIndex = 0, fishSize = 32
    } = params;
    this.position = createVector(x,y);
    this.appearDuration = appearDuration;
    this.vanishDuration = vanishDuration;
    this.life = life;
    this.properFrameCount = 0;
    this.velocity = velocity;
    this.direction = direction;
    this.acceleFactor = acceleFactor;
    this.noiseFactor = noiseFactor;
    this.noiseIndex = noiseIndex;
    this.fishSize = fishSize;
    this.fishScale = {w:1.8*fishSize, h:1.0*fishSize};
    this.alive = true;
  }
  updateUnit(){
    this.direction += this.acceleFactor*(noise(this.noiseIndex, this.properFrameCount*this.noiseFactor)-0.5);
    this.position.add(this.velocity*cos(this.direction), this.velocity*sin(this.direction));

    if(this.position.x < 0) this.position.x += width;
    if(this.position.y < 0) this.position.y += height;
    if(this.position.x > width) this.position.x -= width;
    if(this.position.y > height) this.position.y -= height;
    /*
    if(this.position.x < -vanishMargin) this.alive = false;
    if(this.position.x > width+vanishMargin) this.alive = false;
    if(this.position.y < -vanishMargin) this.alive = false;
    if(this.position.y > height+vanishMargin) this.alive = false;
    */
    this.properFrameCount++;
    if(this.properFrameCount>this.life) this.alive = false;
  }
  drawUnit(){
    if(this.appearDuration > this.properFrameCount){
      const appearAlphaValue = 255*this.properFrameCount/this.appearDuration;
      baseImg.fill(255, appearAlphaValue);
    }else if(this.properFrameCount>this.life-this.vanishDuration){
      const vanishAlphaValue = 255*(this.life-this.properFrameCount)/this.vanishDuration;
      baseImg.fill(255, vanishAlphaValue);
    }else{
      baseImg.fill(255);
    }
    const centers = getCenters(this.position.x, this.position.y, this.fishScale.w, this.fishScale.h, this.direction);
    for(const c of centers){
      baseImg.push();
      baseImg.translate(c.x,c.y);
      baseImg.rotate(this.direction);
      baseImg.scale(this.fishSize);
      baseImg.drawingContext.fill(fishPaths[this.properFrameCount%120]);
      baseImg.pop();
    }
  }
}

// (x,y)が(cx,cy)中心(w,h)サイズangle回転の中に入るかどうかのチェック
function pointInTheRect(x,y,cx,cy,w,h,angle=0){
  // 難しくなくて、(x-cx,y-cy)と(cos,sin)や(-sin,cos)の内積を取ればいい
  const ipX = (x-cx)*cos(angle) + (y-cy)*sin(angle);
  const ipY = -(x-cx)*sin(angle) + (y-cy)*cos(angle);
  if (abs(ipX)>w/2) return false;
  if (abs(ipY)>h/2) return false;
  return true;
}

function getCenters(x,y,w,h,angle=0){
  const result = [{x:x,y:y}];
  const corners = [
    {x:w/2,y:0},{x:0,y:h/2},{x:-w/2,y:0},{x:0,y:-h/2}
  ];
  for(const c of corners){
    const a = c.x;
    const b = c.y;
    c.x = x+a*cos(angle)-b*sin(angle);
    c.y = y+a*sin(angle)+b*cos(angle);
  }
  const directions = [
    {x:-width,y:-height}, {x:0,y:-height},
    {x:width,y:-height}, {x:width,y:0},
    {x:width,y:height}, {x:0,y:height},
    {x:-width,y:height}, {x:-width,y:0}
  ];
  // directionsからひとつ取ってそれをどれかのコーナーに適用する
  // たとえば上向きを適用してキャンバス内に入るなら下にはみ出してるから
  // 上向きを(x,y)に適用したものをresultにぶちこむ
  // その判定がミスった場合に
  // 下側の...この場合は(0,height)と(width,height)が矩形内にあるかどうか調べる
  // というのもねぇ
  // 4頂点が下にはみ出してなくても斜めで角がかすってあれする場合があるんでね。
  const canvasCorners = [
    {x:0,y:0},{x:width,y:0},{x:width,y:height},{x:0,y:height}
  ];
  const canvasCornerIndicesArray = [
    [2],[2,3],[3],[3,0],
    [0],[0,1],[1],[1,2]
  ];
  for(let i=0;i<8;i++){
    const d = directions[i];
    let check = false;
    for(const c of corners){
      if(c.x+d.x<0||c.x+d.x>width)continue;
      if(c.y+d.y<0||c.y+d.y>height)continue;
      check=true;
      break;
    }
    const indices = canvasCornerIndicesArray[i];
    for(let k=0;k<indices.length;k++){
      const cc = canvasCorners[indices[k]];
      if(pointInTheRect(cc.x,cc.y,x,y,w,h,angle)){
        check=true;
        break;
      }
    }
    if(check){
      result.push({x:x+d.x,y:y+d.y});
      continue;
    }
  }
  return result;
}

function createFishPath(c){

  const startAngle = (PI/6)*sin(c*TAU/60);
  let x=300+20*cos(startAngle);
  let y=20*sin(startAngle);
  let _angle=-startAngle*0.6;
  const modifyArray = [];
  //beginShape();
  //vertex(x,y);
  modifyArray.push({x:x,y:y,angle:_angle});
  for(let k=0;k<640;k++){
    x -= cos(_angle);
    y -= sin(_angle);
    const factor = 0.000006 + 0.000002*sin(c*TAU/120);
    _angle += factor*k*sin(c*TAU/60);
    //vertex(x,y);
    modifyArray.push({x:x,y:y,angle:_angle});
  }

  //const result = [];
  const resultPath = new Path2D();

  for(let i=0; i<fishCurve.length; i++){
    const v = fishCurve[i];
    const n = floor(320-v.x*320);
    const f = fract(320-v.x*320);
    const data1 = modifyArray[n];
    const data2 = modifyArray[n+1];
    const lerpedX = (1-f)*data1.x + f*data2.x;
    const lerpedY = (1-f)*data1.y + f*data2.y;
    const lerpedAngle = (1-f)*data1.angle + f*data2.angle;
    const w = createVector(
      lerpedX/320+v.y*cos(lerpedAngle+PI/2),
      lerpedY/320+v.y*sin(lerpedAngle+PI/2)
    );
    if(i===0){
      resultPath.moveTo(w.x,w.y);
    }else{
      resultPath.lineTo(w.x,w.y);
    }
  }
  return resultPath;
}




